import random


def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp_c = 0
    my_d = 0
    for me, op in history:
        if op == 'C':
            opp_c += 1
        if me == 'D':
            my_d += 1

    opp_d = n - opp_c
    last_me, last_op = history[-1]

    # Strong punishment of chronic defectors
    if opp_d >= 3 and opp_d * 2 >= n:
        if last_op == 'D' or opp_d >= n - 1:
            return 'D'

    # Extract value from near-pure cooperators late, cooperate otherwise
    if opp_d == 0:
        if n >= 96:
            return 'D'
        return 'C'

    # If opponent has defected very rarely, be forgiving and mostly cooperative
    if opp_d <= 2:
        if last_op == 'D':
            if rng.random() < 0.5:
                return 'C'
            return 'D'
        if n >= 97:
            return 'D'
        return 'C'

    coop_rate = opp_c / n

    # If we're nearing the end, exploit a cooperative opponent
    if n >= 92:
        if coop_rate >= 0.6:
            return 'D'
        if coop_rate <= 0.3:
            return 'D'

    # Tit-for-tat with forgiveness weighted by opponent cooperation rate
    if last_op == 'D':
        # Recent defection streak
        streak = 0
        for i in range(n - 1, -1, -1):
            if history[i][1] == 'D':
                streak += 1
            else:
                break
        if streak >= 3:
            return 'D'
        # Forgive occasional defection from a generally cooperative opponent
        if coop_rate > 0.7 and streak == 1:
            if rng.random() < 0.65:
                return 'C'
        # Punish otherwise
        if coop_rate > 0.5:
            if rng.random() < 0.35:
                return 'C'
        return 'D'

    # Opponent cooperated last round
    if last_me == 'D':
        # Repair after our defection unless opponent is clearly exploitable
        if coop_rate >= 0.55:
            return 'C'
        if rng.random() < 0.5:
            return 'C'
        return 'D'

    # Both cooperated: detect exploitation opportunities
    if coop_rate >= 0.8 and n >= 20 and n % 7 == 0:
        return 'D'

    return 'C'
